{
  "title": "Query load",
  "timeRange": { "from": "now-1h", "to": "now" },
  "refreshIntervalMs": 15000,
  "panels": [
    {
      "id": "qps-by-source",
      "title": "Queries per second by source",
      "viz": "line",
      "query": {
        "sourceId": "eval-prometheus-demo",
        "promql": "sum by (source) (rate(holotable_query_duration_seconds_count[5m]))"
      },
      "layout": { "x": 0, "y": 0, "w": 6, "h": 4 }
    },
    {
      "id": "p95-latency",
      "title": "p95 query latency",
      "viz": "line",
      "query": {
        "sourceId": "eval-prometheus-demo",
        "promql": "histogram_quantile(0.95, sum by (le) (rate(holotable_query_duration_seconds_bucket[5m])))"
      },
      "layout": { "x": 6, "y": 0, "w": 6, "h": 4 }
    },
    {
      "id": "failed-share",
      "title": "Share of queries that failed",
      "viz": "stat",
      "query": {
        "sourceId": "eval-prometheus-demo",
        "promql": "sum(rate(holotable_query_duration_seconds_count{outcome=\"error\"}[5m])) / sum(rate(holotable_query_duration_seconds_count[5m]))",
        "instant": true
      },
      "layout": { "x": 0, "y": 4, "w": 6, "h": 4 }
    }
  ]
}
